-- Create the database separately (see database/README.md), select it with USE,
-- then run this script. All timestamps are generated by the MySQL server.

CREATE TABLE IF NOT EXISTS loan_applications (
    id INT NOT NULL AUTO_INCREMENT,
    gender VARCHAR(16) NOT NULL,
    married VARCHAR(8) NOT NULL,
    dependents VARCHAR(8) NOT NULL,
    education VARCHAR(16) NOT NULL,
    self_employed VARCHAR(8) NOT NULL,
    applicant_income DECIMAL(12, 2) NOT NULL,
    coapplicant_income DECIMAL(12, 2) NOT NULL,
    loan_amount DECIMAL(12, 2) NOT NULL,
    loan_amount_term DECIMAL(8, 2) NOT NULL,
    credit_history SMALLINT NOT NULL,
    property_area VARCHAR(16) NOT NULL,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (id),
    CONSTRAINT ck_application_income CHECK (applicant_income >= 0),
    CONSTRAINT ck_coapplicant_income CHECK (coapplicant_income >= 0),
    CONSTRAINT ck_loan_amount CHECK (loan_amount >= 0),
    CONSTRAINT ck_loan_amount_term CHECK (loan_amount_term > 0),
    CONSTRAINT ck_credit_history CHECK (credit_history IN (0, 1)),
    INDEX ix_loan_applications_created_at (created_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS predictions (
    id INT NOT NULL AUTO_INCREMENT,
    application_id INT NOT NULL,
    predicted_class CHAR(1) NOT NULL,
    approval_probability DECIMAL(7, 6) NOT NULL,
    rejection_probability DECIMAL(7, 6) NOT NULL,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (id),
    CONSTRAINT fk_predictions_application
        FOREIGN KEY (application_id) REFERENCES loan_applications (id)
        ON DELETE RESTRICT,
    CONSTRAINT ck_predicted_class CHECK (predicted_class IN ('Y', 'N')),
    CONSTRAINT ck_approval_probability
        CHECK (approval_probability BETWEEN 0 AND 1),
    CONSTRAINT ck_rejection_probability
        CHECK (rejection_probability BETWEEN 0 AND 1),
    INDEX ix_predictions_application_id (application_id),
    INDEX ix_predictions_created_at (created_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
